format:
{% if status == 'human-needed' %}<pulse>{% endif %}{% if status == 'human-needed' %}{% set status_hex = '#f38ba8' %}{% set status_icon = 'bell' %}{% elif status == 'active' %}{% set status_hex = '#89b4fa' %}{% set status_icon = 'gear' %}{% elif status == 'drained' %}{% set status_hex = '#a6e3a1' %}{% set status_icon = 'check' %}{% elif status == 'all-quiet' %}{% set status_hex = '#9399b2' %}{% set status_icon = 'folder' %}{% else %}{% set status_hex = '#585b70' %}{% set status_icon = 'app' %}{% endif %}<icon name='{{ status_icon }}'/> <span size='large' weight='bold' foreground='{{ status_hex }}'>{{ status }}</span>{% for repo in repos %}
<span weight='bold' foreground='#cdd6f4'>{{ repo.name }}</span>  <span foreground='#a6e3a1'>{{ repo.agents.active }}A</span> <span foreground='#89b4fa'>{{ repo.agents.idle }}I</span> <span foreground='#f9e2af'>{{ repo.agents.stale }}S</span> <span foreground='#f38ba8'>{{ repo.agents.dead }}D</span>{% endfor %}{% for repo in repos %}{% for item in repo.attention %}
<wrap><span foreground='#f38ba8'>⚠</span> <span foreground='#a6adc8'>{{ repo.name }}:</span> {% if item.kind == 'dead_holding_paths' %}dead <span foreground='#cdd6f4'>{{ item.agent }}</span> holds {% for p in item.paths %}{{ p }}{% if not loop.last %}, {% endif %}{% endfor %} (ttl {{ item.remaining_ttl }}s){% elif item.kind == 'needs_decision' %}needs decision <span foreground='#cdd6f4'>{{ item.bead_id }}</span>{% elif item.kind == 'gate_order_violation' %}gate violation: <span foreground='#cdd6f4'>{{ item.started_id }}</span> before <span foreground='#cdd6f4'>{{ item.open_gate_id }}</span>{% endif %}</wrap>{% endfor %}{% endfor %}{% if status == 'human-needed' %}</pulse>{% endif %}
